const unspentCredits = `-- name: UnspentCredits :many
SELECT id, household_id, child_id, source, redemption_id, granted_by, minutes, seconds, used_seconds, created_at, forfeited_at, forfeited_by, forfeited_seconds FROM screen_time_credit
WHERE household_id = $1 AND child_id = $2 AND used_seconds < seconds
ORDER BY created_at, id
`

type UnspentCreditsParams struct {
	HouseholdID uuid.UUID
	ChildID     uuid.UUID
}

// Oldest first: spending draws on the oldest credit first.
func (q *Queries) UnspentCredits(ctx context.Context, arg UnspentCreditsParams) ([]ScreenTimeCredit, error) {
	rows, err := q.db.Query(ctx, unspentCredits, arg.HouseholdID, arg.ChildID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScreenTimeCredit{}
	for rows.Next() {
		var i ScreenTimeCredit
		if err := rows.Scan(
			&i.ID,
			&i.HouseholdID,
			&i.ChildID,
			&i.Source,
			&i.RedemptionID,
			&i.GrantedBy,
			&i.Minutes,
			&i.Seconds,
			&i.UsedSeconds,
			&i.CreatedAt,
			&i.ForfeitedAt,
			&i.ForfeitedBy,
			&i.ForfeitedSeconds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
